{"path":"api.js","content":"export function createApi(db){
  // Serialize order processing so the stock check and reservation are atomic
  // across concurrent async requests (prevents overselling).
  let queue = Promise.resolve();

  async function processOrder(user, input){
    if(!user) throw Error('unauthorized');
    const quantity = input ? input.quantity : undefined;
    if(typeof quantity !== 'number' || !Number.isFinite(quantity) || !Number.isInteger(quantity) || quantity <= 0){
      throw Error('invalid quantity');
    }
    if(db.stock < quantity) throw Error('out of stock');
    // Reserve stock before the async insert so concurrent requests see it.
    db.stock -= quantity;
    try {
      // Orders are scoped to the authenticated user's tenant, never to the
      // (possibly spoofed) tenant supplied in the input payload.
      return await db.insert({tenant: user.tenant, quantity});
    } catch(e){
      // Insert failed: roll the reservation back so stock is unchanged.
      db.stock += quantity;
      throw e;
    }
  }

  return {
    order(user, input){
      const result = queue.then(() => processOrder(user, input));
      // Keep the chain alive even when this order rejects.
      queue = result.catch(() => {});
      return result;
    },
    async list(user){
      if(!user) throw Error('unauthorized');
      // Tenant isolation: only return orders belonging to the caller's tenant.
      return db.orders.filter(o => o.tenant === user.tenant);
    }
  };
}
"}

{"path":"client.js","content":"export function createClient(fetchOrders){
  const state = {orders: [], loading: false, error: null};
  let requestId = 0;

  return {
    state,
    async refresh(){
      const id = ++requestId;
      state.loading = true;
      try {
        const orders = await fetchOrders();
        // Ignore stale responses: a newer refresh has already started.
        if(id !== requestId) return;
        state.orders = orders;
        state.error = null;
        state.loading = false;
      } catch(e){
        if(id !== requestId) return;
        state.error = e.message;
        state.loading = false;
      }
    }
  };
}
"}

{"path":"regression.test.js","content":"import test from 'node:test';
import assert from 'node:assert/strict';
import {Database} from './db.js';
import {createApi} from './api.js';
import {createClient} from './client.js';

test('regression: order records the authenticated tenant, not the input tenant', async () => {
  const db = new Database(), api = createApi(db);
  await api.order({tenant:'a'}, {tenant:'evil', quantity:1});
  assert.equal(db.orders.length, 1);
  assert.equal(db.orders[0].tenant, 'a');
  assert.equal(db.orders[0].quantity, 1);
});

test('regression: list is scoped per tenant and requires authentication', async () => {
  const db = new Database(), api = createApi(db);
  await api.order({tenant:'a'}, {quantity:1});
  await api.order({tenant:'b'}, {quantity:1});
  const aOrders = await api.list({tenant:'a'});
  const bOrders = await api.list({tenant:'b'});
  assert.equal(aOrders.length, 1);
  assert.equal(aOrders[0].tenant, 'a');
  assert.equal(bOrders.length, 1);
  assert.equal(bOrders[0].tenant, 'b');
  await assert.rejects(() => api.list(null));
  await assert.rejects(() => api.list(undefined));
});

test('regression: concurrent orders never oversell shared stock', async () => {
  const db = new Database(), api = createApi(db); // stock = 3
  const results = await Promise.allSettled(
    Array.from({length: 10}, () => api.order({tenant:'a'}, {quantity:1}))
  );
  const fulfilled = results.filter(x => x.status === 'fulfilled');
  assert.equal(fulfilled.length, 3);
  assert.equal(db.stock, 0);
  assert.equal(db.orders.length, 3);
});

test('regression: rejects invalid quantities without touching stock', async () => {
  const db = new Database(), api = createApi(db);
  for (const bad of [-2, -0.5, 0, 0.5, 1.5, NaN, Infinity, '2', null, undefined]) {
    await assert.rejects(() => api.order({tenant:'a'}, {quantity: bad}));
  }
  assert.equal(db.stock, 3);
  assert.equal(db.orders.length, 0);
});

test('regression: unauthorized order is rejected and leaves state untouched', async () => {
  const db = new Database(), api = createApi(db);
  await assert.rejects(() => api.order(null, {quantity:1}));
  await assert.rejects(() => api.order(undefined, {quantity:1}));
  assert.equal(db.stock, 3);
  assert.equal(db.orders.length, 0);
});

test('regression: failed insert rolls back stock and later orders still work', async () => {
  const db = new Database(), api = createApi(db);
  db.fail = true;
  await assert.rejects(() => api.order({tenant:'a'}, {quantity:2}));
  assert.equal(db.stock, 3);
  assert.equal(db.orders.length, 0);
  // Recovery after the database comes back online.
  db.fail = false;
  await api.order({tenant:'a'}, {quantity:2});
  assert.equal(db.stock, 1);
  assert.equal(db.orders.length, 1);
});

test('regression: concurrent orders with a failing database keep stock intact', async () => {
  const db = new Database(), api = createApi(db); // stock = 3
  db.fail = true;
  const results = await Promise.allSettled(
    Array.from({length: 5}, () => api.order({tenant:'a'}, {quantity:1}))
  );
  assert.equal(results.filter(x => x.status === 'fulfilled').length, 0);
  assert.equal(db.stock, 3);
  assert.equal(db.orders.length, 0);
});

test('regression: stale refresh cannot overwrite newer orders or clear loading early', async () => {
  let resolveOld;
  let calls = 0;
  const c = createClient(() => ++calls === 1
    ? new Promise(r => resolveOld = r)
    : Promise.resolve(['new']));
  const old = c.refresh();
  await c.refresh();
  assert.deepEqual(c.state.orders, ['new']);
  assert.equal(c.state.loading, false); // newest request already finished
  resolveOld(['old']);
  await old;
  assert.deepEqual(c.state.orders, ['new']); // stale response ignored
  assert.equal(c.state.loading, false);
});

test('regression: error from the latest request is preserved and cleared on success', async () => {
  let mode = 'fail';
  const c = createClient(async () => {
    if (mode === 'fail') throw Error('offline');
    return ['ok'];
  });
  await c.refresh();
  assert.equal(c.state.error, 'offline');
  assert.deepEqual(c.state.orders, []);
  assert.equal(c.state.loading, false);
  mode = 'ok';
  await c.refresh();
  assert.equal(c.state.error, null);
  assert.deepEqual(c.state.orders, ['ok']);
  assert.equal(c.state.loading, false);
  mode = 'fail';
  await c.refresh();
  assert.equal(c.state.error, 'offline'); // latest error preserved
});

test('regression: stale failing refresh does not clobber newer state', async () => {
  let rejectOld;
  let calls = 0;
  const c = createClient(() => ++calls === 1
    ? new Promise((_, rej) => rejectOld = rej)
    : Promise.resolve(['new']));
  const old = c.refresh();
  await c.refresh();
  rejectOld(Error('stale failure'));
  await old; // must resolve quietly, stale result ignored
  assert.deepEqual(c.state.orders, ['new']);
  assert.equal(c.state.error, null);
  assert.equal(c.state.loading, false);
});
"}

